 9	    public static int modPow(int base, int exponent, int modulus) {
10	        validateInputs(exponent, modulus);
11	
12	        int normalizedBase = normalizeBase(base, modulus);
13	        int remainingExponent = exponent;
14	        long result = 1 % modulus;
15	
16	        while (remainingExponent > 0) {
17	            if ((remainingExponent & 1) != 0) {
18	                result = multiplyMod(result, normalizedBase, modulus);
19	            }
20	
